#region ******** Windows APIs ********

#region ******** [MySetWindowOpts] ********
$MyCode = @"
using System;
using System.Runtime.InteropServices;

// Return Class for Set Style Function
public class SetStyleReturn
{
  public bool Success { get; set;}
  public int Style { get; set;}

  // Default Constructor - Failed to Set Style
  public SetStyleReturn()
  {
    Success = false;
    Style = 0;
  }

  // Constructor - Successful Set Style
  public SetStyleReturn(int style)
  {
    Success = true;
    Style = style;
  }
}

public enum MyShowWindowCmd : int
{
    SW_HIDE            = 0,  // Hides the window and activates another window
    SW_SHOWNORMAL      = 1,  // Activates and displays a window (restores if minimized/maximized)
    SW_NORMAL          = 1,  // Same as SW_SHOWNORMAL
    SW_SHOWMINIMIZED   = 2,  // Activates and displays a window as minimized
    SW_SHOWMAXIMIZED   = 3,  // Activates and displays a window as maximized
    SW_MAXIMIZE        = 3,  // Same as SW_SHOWMAXIMIZED
    SW_SHOWNOACTIVATE  = 4,  // Displays a window in its most recent size/position, does not activate
    SW_SHOW            = 5,  // Activates and displays a window in current size/position
    SW_MINIMIZE        = 6,  // Minimizes the window and activates the next top‑level window
    SW_SHOWMINNOACTIVE = 7,  // Displays the window minimized, does not activate
    SW_SHOWNA          = 8,  // Displays the window in current state, does not activate
    SW_RESTORE         = 9,  // Activates and displays a window, restoring if minimized/maximized
    SW_SHOWDEFAULT     = 10, // Sets show state based on STARTUPINFO passed to CreateProcess
    SW_FORCEMINIMIZE   = 11  // Minimizes window even if not responding; use only for non‑responsive apps
}

[Flags]
public enum MyWindowStyle : uint
{
    WS_OVERLAPPED      = 0x00000000, // Standard overlapped window (default)
    WS_POPUP           = 0x80000000, // Pop-up window
    WS_CHILD           = 0x40000000, // Child window (cannot have a menu bar)
    WS_MINIMIZE        = 0x20000000, // Window starts minimized
    WS_VISIBLE         = 0x10000000, // Window is initially visible
    WS_DISABLED        = 0x08000000, // Window is initially disabled
    WS_CLIPSIBLINGS    = 0x04000000, // Clips child windows that overlap sibling windows
    WS_CLIPCHILDREN    = 0x02000000, // Clips child windows from drawing in parent's client area
    WS_MAXIMIZE        = 0x01000000, // Window starts maximized
    WS_CAPTION         = 0x00C00000, // Window has a title bar (includes WS_BORDER)
    WS_BORDER          = 0x00800000, // Window has a thin border
    WS_DLGFRAME        = 0x00400000, // Window has a dialog box frame
    WS_VSCROLL         = 0x00200000, // Window has a vertical scroll bar
    WS_HSCROLL         = 0x00100000, // Window has a horizontal scroll bar
    WS_SYSMENU         = 0x00080000, // Window has a system menu (close, maximize, minimize buttons)
    WS_THICKFRAME      = 0x00040000, // Window has a resizable frame
    WS_GROUP           = 0x00020000, // Group box control style
    WS_TABSTOP         = 0x00010000, // Control can receive keyboard focus via TAB
    WS_MINIMIZEBOX     = 0x00020000, // Window has a minimize button
    WS_MAXIMIZEBOX     = 0x00010000, // Window has a maximize button
    WS_OVERLAPPEDWINDOW = WS_OVERLAPPED | WS_CAPTION | WS_SYSMENU | WS_THICKFRAME | WS_MINIMIZEBOX | WS_MAXIMIZEBOX, // Standard resizable window with title bar and system menu
    WS_POPUPWINDOW      = WS_POPUP | WS_BORDER | WS_SYSMENU // Pop-up window with border and system menu
}

[Flags]
public enum MySetWindowPos : uint
{
    SWP_NOSIZE         = 0x0001,  // Retains current size
    SWP_NOMOVE         = 0x0002,  // Retains current position
    SWP_NOZORDER       = 0x0004,  // Retains current Z order
    SWP_NOREDRAW       = 0x0008,  // Does not redraw changes
    SWP_NOACTIVATE     = 0x0010,  // Does not activate the window
    SWP_FRAMECHANGED   = 0x0020,  // Sends WM_NCCALCSIZE after change
    SWP_SHOWWINDOW     = 0x0040,  // Displays the window
    SWP_HIDEWINDOW     = 0x0080,  // Hides the window
    SWP_NOCOPYBITS     = 0x0100,  // Discards client area
    SWP_NOOWNERZORDER  = 0x0200,  // Does not change owner Z order
    SWP_NOSENDCHANGING = 0x0400,  // Prevents WM_WINDOWPOSCHANGING message
    SWP_DRAWFRAME      = SWP_FRAMECHANGED,
    SWP_NOREPOSITION   = SWP_NOOWNERZORDER,
    SWP_DEFERERASE     = 0x2000,  // Prevents erase until next paint
    SWP_ASYNCWINDOWPOS = 0x4000   // If calling thread/process is not owner
}

public class MySetWindowOpts
{
  // Get Console Window Handle
  [DllImport("kernel32.dll")]
  private static extern IntPtr GetConsoleWindow();

  // Enable Window
  [DllImport("user32.dll")]
  [return: MarshalAs(UnmanagedType.Bool)]
  private static extern bool EnableWindow(IntPtr hWnd, bool bEnable);

  // Enable Console Window
  public static bool EnableConsole()
  {
    return EnableWindow(GetConsoleWindow(), true);
  }

  // Disable Console Window
  public static bool DisableConsole()
  {
    return EnableWindow(GetConsoleWindow(), false);
  }

  // Get Foreground Window
  [DllImport("user32.dll", SetLastError = true)]
  public static extern IntPtr GetForegroundWindow();

  // Set Foreground Window
  [DllImport("user32.dll")]
  [return: MarshalAs(UnmanagedType.Bool)]
  public static extern bool SetForegroundWindow(IntPtr hWnd);

  // Set Console Forground Window
  public static bool SetForgroundConsole()
  {
    return SetForegroundWindow(GetConsoleWindow());
  }


  // Show and Hide Window - MyShowWindowCmd
  [DllImport("user32.dll")]
  public static extern bool ShowWindow(IntPtr hWnd, MyShowWindowCmd nCmdShow);

  // Hide Console Window
  public static bool HideConsole()
  {
    return ShowWindow(GetConsoleWindow(), MyShowWindowCmd.SW_HIDE);
  }

  // Show Console Window
  public static bool ShowConsole()
  {
    return ShowWindow(GetConsoleWindow(), MyShowWindowCmd.SW_SHOW);
  }


  // Get Windows Cordinates / Size
  [StructLayout(LayoutKind.Sequential)]
  public struct RECT
  {
    public int Left;
    public int Top;
    public int Right;
    public int Bottom;
  }

  [DllImport("user32.dll")]
  public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

  
  // Get Console Windows Cordinates / Size
  public static RECT GetConsoleSize()
  {
    IntPtr consoleHandle = GetConsoleWindow();
    RECT rect;
    bool check = GetWindowRect(consoleHandle, out rect);
    return rect;
  }

  // GetWindowLong / SetWindowLong Constants
  private const int GWL_STYLE = -16;
  private static readonly IntPtr HWND_TOP = IntPtr.Zero;

  // Get Window Style
  [DllImport("user32.dll")]
  private static extern int GetWindowLongPtr(IntPtr hWnd, int nIndex);

  public static int GetWindowStyle(IntPtr hWnd) 
  {
    return GetWindowLongPtr(hWnd, GWL_STYLE);
  }


  // Set Window Style - MyWindowStyle
  [DllImport("user32.dll")]
  private static extern int SetWindowLongPtr(IntPtr hWnd, int nIndex, int dwNewLong);

  // Set Console Window Style
  public static SetStyleReturn SetConsoleStyle(int dwNewLong, bool applyAction, int X = 0, int Y = 0, int cx = 0, int cy = 0) 
  {
    // Set Console Windows Style
    return SetWindowStyle(GetConsoleWindow(), dwNewLong, applyAction, X, Y, cx, cy);
  }

  // Set Windows Style
  public static SetStyleReturn SetWindowStyle(IntPtr hWnd, int dwNewLong, bool applyAction, int X = 0, int Y = 0, int cx = 0, int cy = 0) 
  {
    // Get Current Style
    int dwOldLong = GetWindowLongPtr(hWnd, GWL_STYLE);
    int chKValue = 0;
    if (applyAction)
    {
      // Apply Style - Add Style Options
      chKValue = SetWindowLongPtr(hWnd, GWL_STYLE, (dwOldLong | dwNewLong));
    }
    else
    {
      // Remove Style - Remove Style Options
      chKValue = SetWindowLongPtr(hWnd, GWL_STYLE, (dwOldLong & (~dwNewLong)));
    }
    if (chKValue == 0)
    {
      // Failed to Set Style
      return new SetStyleReturn();
    }
    else
    {
      MySetWindowPos flags = MySetWindowPos.SWP_FRAMECHANGED;
      // Set Position Flags
      if (X == 0 || Y == 0)
      {
        flags |= MySetWindowPos.SWP_NOMOVE;
      }
      // Set Size Flags
      if (cx == 0 || cy == 0)
      {
        flags |= MySetWindowPos.SWP_NOSIZE;
      }
      // Refresh Window Style and Set Size/Position
      bool result = SetWindowPos(hWnd, HWND_TOP, X, Y, cx, cy, (uint)flags);
      if (result)
      {
        // Return Success / Old Style
        return new SetStyleReturn(dwOldLong);
      }
      else
      {
        // Failed to Refresh Style
        return new SetStyleReturn();
      }
    }
  }

  // Se tWindow Pos - MySetWindowPos
  [DllImport("user32.dll")]
  private static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);

  // Set Console Size and Position
  public static bool SetConsoleSizePosition(int X, int Y, int cx, int cy)
  {
    return SetWindowPos(GetConsoleWindow(), HWND_TOP, X, Y, cx, cy, (uint)MySetWindowPos.SWP_FRAMECHANGED);
  }

  // Set Console Position
  public static bool SetConsolePosition(int X, int Y)
  {
    return SetWindowPos(GetConsoleWindow(), HWND_TOP, X, Y, 0, 0, (uint)(MySetWindowPos.SWP_NOSIZE | MySetWindowPos.SWP_FRAMECHANGED));
  }

  // Set Console Size
  public static bool SetConsoleSize(int cx, int cy)
  {
    return SetWindowPos(GetConsoleWindow(), HWND_TOP, 0, 0, cx, cy, (uint)(MySetWindowPos.SWP_NOMOVE | MySetWindowPos.SWP_FRAMECHANGED));
  }


  // Set Window Size and Position
  public static bool SetWindowSizePosition(IntPtr hWnd, int X, int Y, int cx, int cy)
  {
    return SetWindowPos(hWnd, HWND_TOP, X, Y, cx, cy, (uint)MySetWindowPos.SWP_FRAMECHANGED);
  }

  // Set Window Position
  public static bool SetWindowPosition(IntPtr hWnd, int X, int Y)
  {
    return SetWindowPos(hWnd, HWND_TOP, X, Y, 0, 0, (uint)(MySetWindowPos.SWP_NOSIZE | MySetWindowPos.SWP_FRAMECHANGED));
  }

  // Set Window Size
  public static bool SetWindowSize(IntPtr hWnd, int cx, int cy)
  {
    return SetWindowPos(hWnd, HWND_TOP, 0, 0, cx, cy, (uint)(MySetWindowPos.SWP_NOMOVE | MySetWindowPos.SWP_FRAMECHANGED));
  }
}
"@
#endregion ******** [MySetWindowOpts] ********
Add-Type -TypeDefinition $MyCode -Debug:$False

[System.Console]::Title = "RUNNING: $([MyConfig]::ScriptName) - $([MyConfig]::ScriptVersion)"
if ([MyConfig]::Production)
{
  [Void][MySetWindowOpts]::HideConsole()
}

#region ******** [Extract.MyIcon] ********

#$TempCount = [Extract.MyIcon]::IconCount("C:\Windows\System32\shell32.dll")
#$TempIcon = [Extract.MyIcon]::IconReturn("C:\Windows\System32\shell32.dll", 1, $False)

$MyCode = @"
using System;
using System.Drawing;
using System.Runtime.InteropServices;

namespace Extract
{
  public class MyIcon
  {
    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool DestroyIcon(IntPtr hIcon);

    [DllImport("shell32.dll", CharSet = CharSet.Auto)]
    private static extern uint ExtractIconEx(string szFileName, int nIconIndex, IntPtr[] phiconLarge, IntPtr[] phiconSmall, uint nIcons);

    public static int IconCount(string FileName)
    {
      try
      {
        IntPtr[] LIcons = new IntPtr[1] { IntPtr.Zero };
        IntPtr[] SIcons = new IntPtr[1] { IntPtr.Zero };
        return (int)ExtractIconEx(FileName, -1, LIcons, SIcons, 1);
      }
      catch
      {
      }
      return 0;
    }

    public static Icon IconReturn(string FileName, int IconNum, bool GetLarge)
    {
      IntPtr[] SIcons = new IntPtr[1] { IntPtr.Zero };
      IntPtr[] LIcons = new IntPtr[1] { IntPtr.Zero };
      Icon RetData = null;
      try
      {
        int IconCount = (int)ExtractIconEx(FileName, IconNum, LIcons, SIcons, 1);
        if (GetLarge)
        {
          if (IconCount > 0 && LIcons[0] != IntPtr.Zero)
          {
            RetData = (Icon)Icon.FromHandle(LIcons[0]).Clone();
          }
        }
        else
        {
          if (IconCount > 0 && SIcons[0] != IntPtr.Zero)
          {
            RetData = (Icon)Icon.FromHandle(SIcons[0]).Clone();
          }
        }
      }
      catch
      {
      }
      finally
      {
        foreach (IntPtr ptr in LIcons)
        {
          if (ptr != IntPtr.Zero)
          {
            DestroyIcon(ptr);
          }
        }
        foreach (IntPtr ptr in SIcons)
        {
          if (ptr != IntPtr.Zero)
          {
            DestroyIcon(ptr);
          }
        }
      }
      return RetData;
    }

    public static Icon IconReturn(string FileName, int IconNum)
    {
      return IconReturn(FileName, IconNum, false);
    }
  }
}
"@
Add-Type -TypeDefinition $MyCode -ReferencedAssemblies System.Drawing -Debug:$False
#endregion ******** [Extract.MyIcon] ********

#endregion ******** Windows APIs ********

