  # ************************************************
  #region $ChangeLogBtmPanel = [System.Windows.Forms.Panel]::New()
  $ChangeLogBtmPanel = [System.Windows.Forms.Panel]::New()
  $ChangeLogForm.Controls.Add($ChangeLogBtmPanel)
