    [MyConfig]::AutoExit = 0

    # Cancel Code Goes here

    $CheckBoxOptionForm.DialogResult = [System.Windows.Forms.DialogResult]::Cancel

    Write-Verbose -Message "Exit Click Event for `$CheckBoxOptionBtmRightButton"
  }
