      $CheckedListBoxOptionCheckedListBox.Tag | ForEach-Object -Process { $CheckedListBoxOptionCheckedListBox.SetItemChecked($CheckedListBoxOptionCheckedListBox.Items.IndexOf($PSItem), $True) }
