  [Void]$StringBuilder.AppendLine("      Write-RichTextBox -RichTextBox `$RichTextBox -Text `"Exiting - User Canceled`" -Font ([MyConfig]::Font.Bold) -TextFore ([MyConfig]::Colors.TextBad) -Alignment Center")
