  [Void]$StringBuilder.AppendLine("      Break UserCancel")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    # Pause Processing Loop")
  [Void]$StringBuilder.AppendLine("    If (`$RichTextBox.Parent.Parent.Tag.Pause)")
