  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Set Console Window Style")
  [Void]$StringBuilder.AppendLine("  public static SetStyleReturn SetConsoleStyle(int dwNewLong, bool applyAction, int X = 0, int Y = 0, int cx = 0, int cy = 0) ")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    // Set Console Windows Style")
  [Void]$StringBuilder.AppendLine("    return SetWindowStyle(GetConsoleWindow(), dwNewLong, applyAction, X, Y, cx, cy);")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Set Windows Style")
  [Void]$StringBuilder.AppendLine("  public static SetStyleReturn SetWindowStyle(IntPtr hWnd, int dwNewLong, bool applyAction, int X = 0, int Y = 0, int cx = 0, int cy = 0) ")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    // Get Current Style")
  [Void]$StringBuilder.AppendLine("    int dwOldLong = GetWindowLongPtr(hWnd, GWL_STYLE);")
  [Void]$StringBuilder.AppendLine("    int chKValue = 0;")
  [Void]$StringBuilder.AppendLine("    if (applyAction)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      // Apply Style - Add Style Options")
  [Void]$StringBuilder.AppendLine("      chKValue = SetWindowLongPtr(hWnd, GWL_STYLE, (dwOldLong | dwNewLong));")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      // Remove Style - Remove Style Options")
  [Void]$StringBuilder.AppendLine("      chKValue = SetWindowLongPtr(hWnd, GWL_STYLE, (dwOldLong & (~dwNewLong)));")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    if (chKValue == 0)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      // Failed to Set Style")
  [Void]$StringBuilder.AppendLine("      return new SetStyleReturn();")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      MySetWindowPos flags = MySetWindowPos.SWP_FRAMECHANGED;")
  [Void]$StringBuilder.AppendLine("      // Set Position Flags")
  [Void]$StringBuilder.AppendLine("      if (X == 0 || Y == 0)")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        flags |= MySetWindowPos.SWP_NOMOVE;")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      // Set Size Flags")
  [Void]$StringBuilder.AppendLine("      if (cx == 0 || cy == 0)")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        flags |= MySetWindowPos.SWP_NOSIZE;")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      // Refresh Window Style and Set Size/Position")
  [Void]$StringBuilder.AppendLine("      bool result = SetWindowPos(hWnd, HWND_TOP, X, Y, cx, cy, (uint)flags);")
  [Void]$StringBuilder.AppendLine("      if (result)")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        // Return Success / Old Style")
  [Void]$StringBuilder.AppendLine("        return new SetStyleReturn(dwOldLong);")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      else")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        // Failed to Refresh Style")
  [Void]$StringBuilder.AppendLine("        return new SetStyleReturn();")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
