  [Void]$StringBuilder.AppendLine("public class MyEnumWindows")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  // Get Open Window by Title Bar Name")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError = true)]")
  [Void]$StringBuilder.AppendLine("  private static extern IntPtr FindWindow(string lpClassName, string lpWindowName);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  public static IntPtr FindWindowByTitle(string WindowTitle)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    return FindWindow(null, WindowTitle);")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // List All Open Windows")
  [Void]$StringBuilder.AppendLine("  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`")]")
  [Void]$StringBuilder.AppendLine("  private static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError=true)]")
  [Void]$StringBuilder.AppendLine("  private static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError=true)]")
  [Void]$StringBuilder.AppendLine("  private static extern int GetWindowTextLength(IntPtr hWnd);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`")]")
  [Void]$StringBuilder.AppendLine("  private static extern bool IsWindowVisible(IntPtr hWnd);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Encapsulated method: returns list of window titles and handles")
  [Void]$StringBuilder.AppendLine("  public static List<WindowInfo> GetOpenWindows()")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    List<WindowInfo> windows = new List<WindowInfo>();")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    EnumWindows((hWnd, lParam) =>")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      if (IsWindowVisible(hWnd))")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        int length = GetWindowTextLength(hWnd);")
  [Void]$StringBuilder.AppendLine("        if (length > 0)")
  [Void]$StringBuilder.AppendLine("        {")
  [Void]$StringBuilder.AppendLine("          StringBuilder sb = new StringBuilder(length + 1);")
  [Void]$StringBuilder.AppendLine("          GetWindowText(hWnd, sb, sb.Capacity);")
