  [Void]$StringBuilder.AppendLine("      return true; // continue enumeration")
  [Void]$StringBuilder.AppendLine("    }, IntPtr.Zero);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    return windows;")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("}")
