  [Void]$StringBuilder.AppendLine("  private static extern IntPtr GetConsoleWindow();")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError = true)]")
  [Void]$StringBuilder.AppendLine("  private static extern IntPtr FindWindow(string lpClassName, string lpWindowName);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError = true)]")
  [Void]$StringBuilder.AppendLine("  private static extern bool SetForegroundWindow(IntPtr hWnd);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError = true)]")
  [Void]$StringBuilder.AppendLine("  private static extern IntPtr GetForegroundWindow();")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [DllImport(`"user32.dll`", SetLastError = true)]")
  [Void]$StringBuilder.AppendLine("  private static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Keyboard Event Flags")
  [Void]$StringBuilder.AppendLine("  private const uint KEYEVENTF_KEYDOWN = 0x0000;")
  [Void]$StringBuilder.AppendLine("  private const uint KEYEVENTF_KEYUP = 0x0002;")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Send a single key to the console window")
  [Void]$StringBuilder.AppendLine("  public static void SendKeyToConsole(int keyCode)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr hWnd = GetConsoleWindow();")
  [Void]$StringBuilder.AppendLine("    if (hWnd != IntPtr.Zero)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      SendKeyToWindowHandle(hWnd, keyCode);")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Send multiple keys to the console window")
  [Void]$StringBuilder.AppendLine("  public static void SendKeysToConsole(string keys)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr hWnd = GetConsoleWindow();")
  [Void]$StringBuilder.AppendLine("    if (hWnd != IntPtr.Zero)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      SendKeysToWindowHandle(hWnd, keys);")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Send a single key to a window by its title")
  [Void]$StringBuilder.AppendLine("  public static void SendKeyToWindow(string windowTitle, int keyCode)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr hWnd = FindWindow(null, windowTitle);")
  [Void]$StringBuilder.AppendLine("    if (hWnd != IntPtr.Zero)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      SendKeyToWindowHandle(hWnd, keyCode);")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Send multiple keys to a window by its title")
  [Void]$StringBuilder.AppendLine("  public static void SendKeysToWindow(string windowTitle, string keys)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr hWnd = FindWindow(null, windowTitle);")
  [Void]$StringBuilder.AppendLine("    if (hWnd != IntPtr.Zero)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      SendKeysToWindowHandle(hWnd, keys);")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Core method to send key(s) to a window handle")
  [Void]$StringBuilder.AppendLine("  public static void SendKeyToWindowHandle(IntPtr hWnd, int keyCode)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr originalWindow = GetForegroundWindow();")
  [Void]$StringBuilder.AppendLine("    SetForegroundWindow(hWnd);")
  [Void]$StringBuilder.AppendLine("    System.Threading.Thread.Sleep(100);")
  [Void]$StringBuilder.AppendLine("    keybd_event((byte)keyCode, 0, KEYEVENTF_KEYDOWN, UIntPtr.Zero);")
  [Void]$StringBuilder.AppendLine("    keybd_event((byte)keyCode, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);")
  [Void]$StringBuilder.AppendLine("    SetForegroundWindow(originalWindow);")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  // Core method to send multiple keys to a window handles")
  [Void]$StringBuilder.AppendLine("  public static void SendKeysToWindowHandle(IntPtr hWnd, string keys)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    IntPtr originalWindow = GetForegroundWindow();")
  [Void]$StringBuilder.AppendLine("    SetForegroundWindow(hWnd);")
  [Void]$StringBuilder.AppendLine("    System.Threading.Thread.Sleep(100);")
  [Void]$StringBuilder.AppendLine("    foreach (char c in keys)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      int keyCode = (int)char.ToUpper(c);")
  [Void]$StringBuilder.AppendLine("      keybd_event((byte)keyCode, 0, KEYEVENTF_KEYDOWN, UIntPtr.Zero);")
  [Void]$StringBuilder.AppendLine("      keybd_event((byte)keyCode, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);")
  [Void]$StringBuilder.AppendLine("      System.Threading.Thread.Sleep(50);")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    SetForegroundWindow(originalWindow);")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("`"@")
