  [Void]$StringBuilder.AppendLine("namespace My")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  using System;")
  [Void]$StringBuilder.AppendLine("  using System.Runtime.InteropServices;")
