  [Void]$StringBuilder.AppendLine("      string password = (string)networkCredential.GetType().GetProperty(`"Password`").GetValue(networkCredential, null);")
  [Void]$StringBuilder.AppendLine("      string userName = (string)credentialType.GetProperty(`"UserName`").GetValue(Credential, null);")
  [Void]$StringBuilder.AppendLine("      InitializeCredential(userName, password);")
