  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  if ([String]::IsNullOrEmpty(([Management.Automation.PSTypeName]::New(`"System.DirectoryServices.AccountManagement.ContextType`")).Type))")
