  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Verify User DN is not Null")
  [Void]$StringBuilder.AppendLine("  if ([String]::IsNullOrEmpty(`$UserDN))")
