  #region function ConvertTo-EncodeCommand
  [Void]$StringBuilder.AppendLine("#region function ConvertTo-EncodeCommand")
  [Void]$StringBuilder.AppendLine("function ConvertTo-EncodeCommand ()")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  <#")
  [Void]$StringBuilder.AppendLine("    .SYNOPSIS")
  [Void]$StringBuilder.AppendLine("      Encodes a powershell command")
  [Void]$StringBuilder.AppendLine("    .DESCRIPTION")
  [Void]$StringBuilder.AppendLine("      Encodes a powershell command")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Command")
  [Void]$StringBuilder.AppendLine("      Command to be Encoded / Decoded")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Decode")
  [Void]$StringBuilder.AppendLine("      Decode Switch")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      ConvertTo-EncodeCommand -Command [<String>]")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      ConvertTo-EncodeCommand -Command [<String>] -Decode")
  [Void]$StringBuilder.AppendLine("    .LINK")
  [Void]$StringBuilder.AppendLine("  #>")
  [Void]$StringBuilder.AppendLine("  [CmdletBinding(DefaultParameterSetName = `"Encode`")]")
  [Void]$StringBuilder.AppendLine("  param (")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlock`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$ScriptBlock,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPath`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$ScriptPath,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"Encode`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"Decode`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Command,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"Decode`")]")
  [Void]$StringBuilder.AppendLine("    [Switch]`$Decode")
  [Void]$StringBuilder.AppendLine("  )")
  [Void]$StringBuilder.AppendLine("  Write-Verbose -Message `"Enter Function ConvertTo-EncodeCommand`"")
  [Void]$StringBuilder.AppendLine("  ")
  [Void]$StringBuilder.AppendLine("  Switch (`$PSCmdlet.ParameterSetName)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `"Decode`"")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$Decoded = [System.Text.Encoding]::Unicode.GetString([Convert]::FromBase64String(`$Command))")
  [Void]$StringBuilder.AppendLine("      `$Encoded = `$Command")
  [Void]$StringBuilder.AppendLine("      Break")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    `"Encode`"")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$Decoded = `$Command")
  [Void]$StringBuilder.AppendLine("      `$Encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes(`$Command))")
  [Void]$StringBuilder.AppendLine("      Break")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    `"ScriptBlock`"")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$Decoded = `$ScriptBlock.ToString()")
  [Void]$StringBuilder.AppendLine("      `$Encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes(`$ScriptBlock.ToString()))")
  [Void]$StringBuilder.AppendLine("      Break")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    `"ScriptPath`"")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$TmpScriptData = [System.IO.File]::ReadAllText(`$ScriptPath)")
  [Void]$StringBuilder.AppendLine("      `$Decoded = `$TmpScriptData")
  [Void]$StringBuilder.AppendLine("      `$Encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes(`$TmpScriptData))")
  [Void]$StringBuilder.AppendLine("      Break")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  ")
  [Void]$StringBuilder.AppendLine("  [PSCustomObject]@{")
  [Void]$StringBuilder.AppendLine("    `"Decoded`"   = `$Decoded")
  [Void]$StringBuilder.AppendLine("    `"DecodeLen`" = `$Decoded.Length")
  [Void]$StringBuilder.AppendLine("    `"Encoded`"   = `$Encoded")
  [Void]$StringBuilder.AppendLine("    `"EncodeLen`" = `$Encoded.Length")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  ")
  [Void]$StringBuilder.AppendLine("  Write-Verbose -Message `"Exit Function ConvertTo-EncodeCommand`"")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("#endregion function ConvertTo-EncodeCommand")
  [Void]$StringBuilder.AppendLine("")
  #endregion function ConvertTo-EncodeCommand
  
