  #region function Create-MyScheduledTask
  [Void]$StringBuilder.AppendLine("#region function Create-MyScheduledTask")
  [Void]$StringBuilder.AppendLine("Function Create-MyScheduledTask()")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  <#")
  [Void]$StringBuilder.AppendLine("    .SYNOPSIS")
  [Void]$StringBuilder.AppendLine("      Executes a Scheduled Task as the Local System Account")
  [Void]$StringBuilder.AppendLine("    .DESCRIPTION")
  [Void]$StringBuilder.AppendLine("      Executes a Scheduled Task as the Local System Account")
  [Void]$StringBuilder.AppendLine("    .PARAMETER ComputerName")
