  [Void]$StringBuilder.AppendLine("      Do not Delete the Scheduled Task")
  [Void]$StringBuilder.AppendLine("    .PARAMETER ConnectAs")
  [Void]$StringBuilder.AppendLine("      Credential to Connect to Remote Computer")
  [Void]$StringBuilder.AppendLine("    .PARAMETER RunTaskAs")
  [Void]$StringBuilder.AppendLine("      Credential to Run the Task As")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      Create-MyScheduledTask -ComputerName `$ComputerName -Command `$Command -Arguments `$Arguments")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
