  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      4/8/2024 - Initial Release")
  [Void]$StringBuilder.AppendLine("  #>")
  [Void]$StringBuilder.AppendLine("  [CmdletBinding(DefaultParameterSetName = `"Command`")]")
  [Void]$StringBuilder.AppendLine("  Param (")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ValueFromPipeline = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String[]]`$ComputerName = [System.Environment]::MachineName,")
  [Void]$StringBuilder.AppendLine("    [String]`$Path = `"\`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$Name = `"Test Task - `$([Environment]::UserName)`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"Command`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandStartup`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Command = `"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"Command`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandStartup`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Arguments = `" -NoProfile -ExecutionPolicy ByPass -Command ```"& { Get-Command -Name 'Get-Command' | Out-File -FilePath 'C:\Get-Command.txt' }```"`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlock`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockStartup`")]")
  [Void]$StringBuilder.AppendLine("    [ScriptBlock]`$ScriptBlock = { Get-Command -Name `"Get-Command`" | Out-File -FilePath `"C:\Get-Command.txt`" },")
  [Void]$StringBuilder.AppendLine("    [ValidateScript({ [System.IO.File]::Exists(`$PSItem) })]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPath`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathStartup`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$ScriptPath = `"C:\MyScripts\SampeScript.ps1`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathLogon`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockLogon`")]")
  [Void]$StringBuilder.AppendLine("    [Switch]`$AtLogon,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandStartup`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockStartup`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathStartup`")]")
  [Void]$StringBuilder.AppendLine("    [Switch]`$AtStartup,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathTime`")]")
  [Void]$StringBuilder.AppendLine("    [DateTime]`$AtTime,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"ScriptBlockTime`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"ScriptPathTime`")]")
  [Void]$StringBuilder.AppendLine("    [ValidateSet(`"Once`", `"Daily`", `"Weekly`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Recurrence = `"Once`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"CommandRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptBlockRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True, ParameterSetName = `"ScriptPathRun`")]")
  [Void]$StringBuilder.AppendLine("    [Switch]`$RunTask,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"CommandRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"ScriptBlockRun`")]")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$False, ParameterSetName = `"ScriptPathRun`")]")
  [Void]$StringBuilder.AppendLine("    [Switch]`$NoDelete,")
  [Void]$StringBuilder.AppendLine("    [PSCredential]`$ConnectAs,")
  [Void]$StringBuilder.AppendLine("    [PSCredential]`$RunTaskAs")
  [Void]$StringBuilder.AppendLine("  )")
  [Void]$StringBuilder.AppendLine("  Begin")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    Write-Verbose -Message `"Enter Function Create-MyScheduledTask Begin Block`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    # Task Action / Command to Execute")
  [Void]$StringBuilder.AppendLine("    Switch -wildcard (`$PSCmdlet.ParameterSetName)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `"Command*`"")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Execute Any Command")
  [Void]$StringBuilder.AppendLine("        `$TaskAction = @{")
  [Void]$StringBuilder.AppendLine("          `"Execute`" = `$Command")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("        If (`$PSBoundParameters.ContainsKey(`"Arguments`"))")
  [Void]$StringBuilder.AppendLine("        {")
  [Void]$StringBuilder.AppendLine("          `$TaskAction.Add(`"Argument`", `$Arguments)")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("        Break")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      `"ScriptBlock*`"")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Execute a Script Block")
