  [Void]$StringBuilder.AppendLine("        `$TaskAction = @{")
  [Void]$StringBuilder.AppendLine("          `"Execute`"  = `"`$([Environment]::SystemDirectory)\WindowsPowerShell\v1.0\powershell.exe`"")
  [Void]$StringBuilder.AppendLine("          `"Argument`" = `" -NoProfile -ExecutionPolicy ByPass -EncodedCommand `$(`$EncodedCommand)`"")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("        Break")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      `"ScriptPath*`"")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Load and Execute a Script")
  [Void]$StringBuilder.AppendLine("        `$TmpScriptData = [System.IO.File]::ReadAllText(`$ScriptPath)")
  [Void]$StringBuilder.AppendLine("        `$EncodedCommand = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes(`$TmpScriptData))")
  [Void]$StringBuilder.AppendLine("        If (`$EncodedCommand.Length -le 32700)")
  [Void]$StringBuilder.AppendLine("        {")
  [Void]$StringBuilder.AppendLine("          `$TaskAction = @{")
  [Void]$StringBuilder.AppendLine("            `"Execute`"  = `"`$([Environment]::SystemDirectory)\WindowsPowerShell\v1.0\powershell.exe`"")
  [Void]$StringBuilder.AppendLine("            `"Argument`" = `" -NoProfile -ExecutionPolicy ByPass -EncodedCommand `$(`$EncodedCommand)`"")
