  [Void]$StringBuilder.AppendLine("        Break")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    # Fix Task Path")
  [Void]$StringBuilder.AppendLine("    `$TmpTaskPath = `"\`$(`$Path.Trim(`"\`"))\`".Replace(`"\\`", `"\`")")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    # Run as Specific Time")
  [Void]$StringBuilder.AppendLine("    If (`$PSCmdlet.ParameterSetName -like `"*Time`")")
