  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        `"Once`" { `$TmpTaskTime = @{ `"Once`" = `$True }; Break }")
  [Void]$StringBuilder.AppendLine("        `"Daily`" { `$TmpTaskTime = @{ `"Daily`" = `$True }; Break }")
  [Void]$StringBuilder.AppendLine("        `"Weekly`" { `$TmpTaskTime = @{ `"Weekly`" = `$True }; Break }")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      `$TmpTaskTime.Add(`"At`", `$AtTime)")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    Write-Verbose -Message `"Exit Function Create-MyScheduledTask Begin Block`"")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  Process")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    Write-Verbose -Message `"Enter Function Create-MyScheduledTask Process Block`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    # Loop and Proccess all Values")
  [Void]$StringBuilder.AppendLine("    ForEach (`$Computer In `$ComputerName)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$InvokeResult = [PSCustomObject]@{")
