  [Void]$StringBuilder.AppendLine("        `"Message`"      = `"`"")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      Try")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Verify Computer is On-Line")
  [Void]$StringBuilder.AppendLine("        If (Test-Connection -Quiet -Count 2 -ComputerName `$Computer)")
  [Void]$StringBuilder.AppendLine("        {")
  [Void]$StringBuilder.AppendLine("          # Connect to Remote Workstation")
  [Void]$StringBuilder.AppendLine("          if (`$PSBoundParameters.ContainsKey(`"ConnectAs`"))")
