  [Void]$StringBuilder.AppendLine("          Get-ScheduledTask -CimSession `$TmpCimSession -TaskPath `$TmpTaskPath -TaskName `$Name -ErrorAction SilentlyContinue | Unregister-ScheduledTask -CimSession `$TmpCimSession -Confirm:`$False")
  [Void]$StringBuilder.AppendLine("          # Create New Task")
  [Void]$StringBuilder.AppendLine("          `$TmpAction = New-ScheduledTaskAction -CimSession `$TmpCimSession @TaskAction")
