  [Void]$StringBuilder.AppendLine("            `$NewTaskParams.Add(`"Principal`", `$TmpPrincipal)")
  [Void]$StringBuilder.AppendLine("          }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("          # Create Optional Trigger")
  [Void]$StringBuilder.AppendLine("          Switch -wildcard (`$PSCmdlet.ParameterSetName)")
  [Void]$StringBuilder.AppendLine("          {")
  [Void]$StringBuilder.AppendLine("            `"*Time`"")
  [Void]$StringBuilder.AppendLine("            {")
  [Void]$StringBuilder.AppendLine("              `$NewTaskParams.Add(`"Trigger`", (New-ScheduledTaskTrigger @TmpTaskTime))")
  [Void]$StringBuilder.AppendLine("              Break")
  [Void]$StringBuilder.AppendLine("            }")
  [Void]$StringBuilder.AppendLine("            `"*Logon`"")
