  [Void]$StringBuilder.AppendLine("              Break")
  [Void]$StringBuilder.AppendLine("            }")
  [Void]$StringBuilder.AppendLine("            `"*Startup`"")
  [Void]$StringBuilder.AppendLine("            {")
  [Void]$StringBuilder.AppendLine("              `$NewTaskParams.Add(`"Trigger`", (New-ScheduledTaskTrigger -AtStartup))")
  [Void]$StringBuilder.AppendLine("              Break")
  [Void]$StringBuilder.AppendLine("            }")
  [Void]$StringBuilder.AppendLine("          }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("          # Register the New Task")
  [Void]$StringBuilder.AppendLine("          `$TmpNewTask = Register-ScheduledTask @NewTaskParams")
  [Void]$StringBuilder.AppendLine("          If (`$RunTask.IsPresent)")
  [Void]$StringBuilder.AppendLine("          {")
  [Void]$StringBuilder.AppendLine("            # Execute New Task")
