  [Void]$StringBuilder.AppendLine("            `$TmpNewTask | Start-ScheduledTask -CimSession `$TmpCimSession")
  [Void]$StringBuilder.AppendLine("            Start-Sleep -Milliseconds 1000")
  [Void]$StringBuilder.AppendLine("            While ((`$TmpNewTask | Get-ScheduledTask -CimSession `$TmpCimSession).State -eq `"Running`")")
