  [Void]$StringBuilder.AppendLine("          `$TmpCimSession | Remove-CimSession")
  [Void]$StringBuilder.AppendLine("          # Update Status")
  [Void]$StringBuilder.AppendLine("          `$InvokeResult.Success = `$True")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("        Else")
  [Void]$StringBuilder.AppendLine("        {")
  [Void]$StringBuilder.AppendLine("          # System is Off-Line")
  [Void]$StringBuilder.AppendLine("          `$InvokeResult.Message = `"Off-Line`"")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      Catch")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Return Error Message")
  [Void]$StringBuilder.AppendLine("        `$InvokeResult.Message = `$Error[0].Message")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      # Return Results to Pipeline")
  [Void]$StringBuilder.AppendLine("      `$InvokeResult")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    Write-Verbose -Message `"Exit Function Create-MyScheduledTask Process Block`"")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("#endregion function Create-MyScheduledTask")
