  #region function Get-MyOAuthToken
  [Void]$StringBuilder.AppendLine("#region function Get-MyOAuthToken")
  [Void]$StringBuilder.AppendLine("function Get-MyOAuthToken")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  <#")
  [Void]$StringBuilder.AppendLine("    .SYNOPSIS")
  [Void]$StringBuilder.AppendLine("      Gets an OAuth 2.0 delegated user token by prompting for interactive login.")
  [Void]$StringBuilder.AppendLine("    .DESCRIPTION")
  [Void]$StringBuilder.AppendLine("      Opens an interactive sign-in window, prompts the user to authenticate, and exchanges")
  [Void]$StringBuilder.AppendLine("      the authorization code for an access token without requiring a client secret.")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      The app registration must be configured as a public client and must allow the")
  [Void]$StringBuilder.AppendLine("      specified redirect URI.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER TenantID")
  [Void]$StringBuilder.AppendLine("      Tenant ID (GUID) for the Microsoft Entra ID tenant used for token acquisition.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER ClientID")
  [Void]$StringBuilder.AppendLine("      Application (client) ID (GUID) of the app registration requesting the token.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER RedirectUri")
  [Void]$StringBuilder.AppendLine("      Redirect URI registered on the app. Default is https://localhost/.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER State")
  [Void]$StringBuilder.AppendLine("      State value sent with the authorization request.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Scope")
  [Void]$StringBuilder.AppendLine("      Resource scopes for the token request. Default is https://graph.microsoft.com/.default.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Prompt")
  [Void]$StringBuilder.AppendLine("      Prompt behavior for the user login window. Default is login.")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      `$AuthToken = Get-MyOAuthToken -TenantID `$TenantID -ClientID `$ClientID")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Requests a delegated Graph token using the default login prompt.")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      `$AuthToken = Get-MyOAuthToken -TenantID `$TenantID -ClientID `$ClientID -Scope `"https://`$(`$TenantName).sharepoint.com/.default`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Requests a delegated SharePoint token.")
  [Void]$StringBuilder.AppendLine("    .NOTES")
  [Void]$StringBuilder.AppendLine("      Original Code By Robert Pollock")
  [Void]$StringBuilder.AppendLine("      Updated Function By Ken Sweet")
  [Void]$StringBuilder.AppendLine("  #>")
  [Void]$StringBuilder.AppendLine("  [CmdletBinding()]")
  [Void]$StringBuilder.AppendLine("  param (")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$TenantID,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$ClientID,")
  [Void]$StringBuilder.AppendLine("    [String]`$RedirectUri = `"https://localhost/`",")
  [Void]$StringBuilder.AppendLine("    [String]`$State = `"MyState`",")
  [Void]$StringBuilder.AppendLine("    [String[]]`$Scope = `"https://graph.microsoft.com/.default`",")
  [Void]$StringBuilder.AppendLine("    [ValidateSet(`"login`", `"select_account`", `"consent`", `"none`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Prompt = `"none`"")
  [Void]$StringBuilder.AppendLine("  )")
  [Void]$StringBuilder.AppendLine("  Write-Verbose -Message `"Enter Function Get-MyOAuthToken`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  if ([String]::IsNullOrEmpty(([Management.Automation.PSTypeName]::New(`"System.Web.HttpUtility`")).Type))")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [Void][System.Reflection.Assembly]::LoadWithPartialName(`"System.Web`")")
  [Void]$StringBuilder.AppendLine("    [Void][System.Reflection.Assembly]::LoadWithPartialName(`"System.Windows.Forms`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  try")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    # Create PKCE values for the interactive authorization code flow")
  [Void]$StringBuilder.AppendLine("    `$RandomBytes = New-Object Byte[] 32")
  [Void]$StringBuilder.AppendLine("    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes(`$RandomBytes)")
  [Void]$StringBuilder.AppendLine("    `$CodeVerifier = [System.Convert]::ToBase64String(`$RandomBytes) -replace '\+', '-' -replace '/', '_' -replace '='")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    `$Sha256 = [System.Security.Cryptography.SHA256]::Create()")
  [Void]$StringBuilder.AppendLine("    `$CodeChallengeBytes = `$Sha256.ComputeHash([System.Text.Encoding]::UTF8.GetBytes(`$CodeVerifier))")
  [Void]$StringBuilder.AppendLine("    `$CodeChallenge = [System.Convert]::ToBase64String(`$CodeChallengeBytes) -replace '\+', '-' -replace '/', '_' -replace '='")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    `$TempRedirectUri = [System.Web.HttpUtility]::UrlEncode(`$RedirectUri)")
  [Void]$StringBuilder.AppendLine("    `$TempScope = [System.Web.HttpUtility]::UrlEncode((`$Scope -join `" `"))")
  [Void]$StringBuilder.AppendLine("    `$AuthUri = `"https://login.microsoftonline.com/`$(`$TenantID)/oauth2/v2.0/authorize?client_id=`$(`$ClientID)&state=`$(`$State)&redirect_uri=`$(`$TempRedirectUri)&scope=`$(`$TempScope)&response_type=code&response_mode=query&prompt=`$(`$Prompt)&code_challenge=`$(`$CodeChallenge)&code_challenge_method=S256`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    #region `$OADForm = [System.Windows.Forms.Form]::New()")
  [Void]$StringBuilder.AppendLine("    `$OADForm = [System.Windows.Forms.Form]::New()")
  [Void]$StringBuilder.AppendLine("    `$OADForm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedToolWindow")
  [Void]$StringBuilder.AppendLine("    `$OADForm.Size = [System.Drawing.Size]::New(480, 680)")
  [Void]$StringBuilder.AppendLine("    `$OADForm.TopLevel = `$True")
  [Void]$StringBuilder.AppendLine("    `$OADForm.TopMost = `$True")
  [Void]$StringBuilder.AppendLine("    #endregion `$OADForm = [System.Windows.Forms.Form]::New()")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    # Center and Show Form")
  [Void]$StringBuilder.AppendLine("    `$Screen = ([System.Windows.Forms.Screen]::FromControl(`$OADForm)).WorkingArea")
  [Void]$StringBuilder.AppendLine("    `$OADForm.Left = [Math]::Floor((`$Screen.Width - `$OADForm.Width) / 2)")
  [Void]$StringBuilder.AppendLine("    `$OADForm.Top = [Math]::Floor((`$Screen.Height - `$OADForm.Height) / 2)")
  [Void]$StringBuilder.AppendLine("    `$OADForm.add_Shown({ `$This.Activate() })")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    #region `$OADWebBrowser = [System.Windows.Forms.WebBrowser]::New()")
  [Void]$StringBuilder.AppendLine("    `$OADWebBrowser = [System.Windows.Forms.WebBrowser]::New()")
  [Void]$StringBuilder.AppendLine("    `$OADForm.Controls.Add(`$OADWebBrowser)")
  [Void]$StringBuilder.AppendLine("    `$OADWebBrowser.Location = [System.Drawing.Point]::New(4, 4)")
