  #region function Get-MyOAuthCertToken
  [Void]$StringBuilder.AppendLine("#region function Get-MyOAuthCertToken")
  [Void]$StringBuilder.AppendLine("function Get-MyOAuthCertToken")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  <#")
  [Void]$StringBuilder.AppendLine("    .SYNOPSIS")
  [Void]$StringBuilder.AppendLine("      Gets an OAuth 2.0 client credentials token by using a certificate-based client assertion.")
  [Void]$StringBuilder.AppendLine("    .DESCRIPTION")
  [Void]$StringBuilder.AppendLine("      Builds and signs a JWT client assertion with the private key of a local certificate,")
  [Void]$StringBuilder.AppendLine("      submits it to the Microsoft Entra ID v2 token endpoint, and returns a hashtable")
  [Void]$StringBuilder.AppendLine("      containing authorization header values and token expiration metadata.")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      On authentication failure, the function returns a hashtable with ExpiresIn = 0.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER TenantID")
  [Void]$StringBuilder.AppendLine("      Tenant ID (GUID) for the Microsoft Entra ID tenant used for token acquisition.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER ClientID")
  [Void]$StringBuilder.AppendLine("      Application (client) ID (GUID) of the app registration requesting the token.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Certificate")
  [Void]$StringBuilder.AppendLine("      Certificate thumbprint for the certificate in Cert:\CurrentUser\My used to sign")
  [Void]$StringBuilder.AppendLine("      the client assertion JWT.")
  [Void]$StringBuilder.AppendLine("    .PARAMETER Scope")
  [Void]$StringBuilder.AppendLine("      Resource scope for the token request. Default is https://graph.microsoft.com/.default.")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      `$AuthToken = Get-MyOAuthCertToken -TenantID `$TenantID -ClientID `$ClientID -Certificate `$Thumbprint")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Requests a token using the default Graph scope.")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      if (`$AuthToken.ExpiresIn -lt [DateTime]::Now.ToFileTime())")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        `$AuthToken = Get-MyOAuthCertToken -TenantID `$TenantID -ClientID `$ClientID -Certificate `$Thumbprint")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Refreshes the token when it is close to expiration.")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
  [Void]$StringBuilder.AppendLine("      `$AuthToken = Get-MyOAuthCertToken -TenantID `$TenantID -ClientID `$ClientID -Certificate `$Thumbprint -Scope `"https://management.azure.com/.default`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Requests a token for Azure Resource Manager instead of Microsoft Graph.")
  [Void]$StringBuilder.AppendLine("    .NOTES")
  [Void]$StringBuilder.AppendLine("      Function by Ken Sweet.")
  [Void]$StringBuilder.AppendLine("  #>")
  [Void]$StringBuilder.AppendLine("  [CmdletBinding()]")
  [Void]$StringBuilder.AppendLine("  param (")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$TenantID,")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$ClientID,")
  [Void]$StringBuilder.AppendLine("    [ValidateSet(`"CurrentUser`", `"LocalMachine`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Location = `"LocalMachine`",")
  [Void]$StringBuilder.AppendLine("    [ValidateSet(`"My`", `"TrustedPeople`", `"TrustedPublisher`")]")
  [Void]$StringBuilder.AppendLine("    [String]`$Store = `"My`",")
  [Void]$StringBuilder.AppendLine("    [parameter(Mandatory = `$True)]")
  [Void]$StringBuilder.AppendLine("    [String]`$Certificate,")
  [Void]$StringBuilder.AppendLine("    [String]`$Scope = `"https://graph.microsoft.com/.default`"")
  [Void]$StringBuilder.AppendLine("  )")
