  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  try")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$Cert = Get-Item -Path `"Cert:\`$(`$Location)\`$(`$Store)\`$(`$Certificate)`"")
  [Void]$StringBuilder.AppendLine("    if (`$Cert.Thumbprint -eq `$Certificate)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$TokenUri = `"https://login.microsoftonline.com/`$(`$TenantID)/oauth2/v2.0/token`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Create the JWT header with the certificate")
  [Void]$StringBuilder.AppendLine("      `$JWTHeader = @{")
  [Void]$StringBuilder.AppendLine("        alg = `"RS256`"")
  [Void]$StringBuilder.AppendLine("        typ = `"JWT`"")
  [Void]$StringBuilder.AppendLine("        x5t = [System.Convert]::ToBase64String(`$Cert.GetCertHash()) -replace '\+', '-' -replace '/', '_' -replace '='")
