  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Create the JWT payload with required claims")
  [Void]$StringBuilder.AppendLine("      `$JWTPayLoad = @{")
  [Void]$StringBuilder.AppendLine("        iss = `$ClientID")
  [Void]$StringBuilder.AppendLine("        sub = `$ClientID")
  [Void]$StringBuilder.AppendLine("        aud = `$TokenUri")
  [Void]$StringBuilder.AppendLine("        exp = ([System.DateTimeOffset]::UtcNow.AddMinutes(10)).ToUnixTimeSeconds()")
  [Void]$StringBuilder.AppendLine("        iat = [System.DateTimeOffset]::UtcNow.ToUnixTimeSeconds()")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Convert JWT Payload to base64")
  [Void]$StringBuilder.AppendLine("      `$EncodedJWTPayload = [System.Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes((`$JWTPayload | ConvertTo-Json))) -replace '\+', '-' -replace '/', '_' -replace '='")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Join header and Payload with `".`" to create a valid (unsigned) JWT")
  [Void]$StringBuilder.AppendLine("      `$SignatureInput = `"`$(`$EncodedJWTHeader).`$(`$EncodedJWTPayload)`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Define RSA signature and hashing algorithm")
  [Void]$StringBuilder.AppendLine("      `$RSAPadding = [System.Security.Cryptography.RSASignaturePadding]::Pkcs1")
  [Void]$StringBuilder.AppendLine("      `$HashAlgorithm = [System.Security.Cryptography.HashAlgorithmName]::SHA256")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Create a signature of the JWT")
  [Void]$StringBuilder.AppendLine("      `$PrivateKey = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey(`$Cert)")
  [Void]$StringBuilder.AppendLine("      `$Signature = [System.Convert]::ToBase64String(`$PrivateKey.SignData([System.Text.Encoding]::UTF8.GetBytes(`$SignatureInput), `$HashAlgorithm, `$RSAPadding)) -replace '\+', '-' -replace '/', '_' -replace '='")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Combine header, payload, and signature to create the JWT")
  [Void]$StringBuilder.AppendLine("      `$JWT = `"`$(`$SignatureInput).`$(`$Signature)`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Create a hash with body parameters")
  [Void]$StringBuilder.AppendLine("      `$Body = @{")
  [Void]$StringBuilder.AppendLine("        client_id             = `$ClientID")
  [Void]$StringBuilder.AppendLine("        client_assertion      = `$JWT")
  [Void]$StringBuilder.AppendLine("        client_assertion_type = `"urn:ietf:params:oauth:client-assertion-type:jwt-bearer`"")
  [Void]$StringBuilder.AppendLine("        scope                 = `$Scope")
  [Void]$StringBuilder.AppendLine("        grant_type            = `"client_credentials`"")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Splat the parameters for Invoke-Restmethod for cleaner code")
  [Void]$StringBuilder.AppendLine("      `$PostSplat = @{")
  [Void]$StringBuilder.AppendLine("        ContentType = 'application/x-www-form-urlencoded'")
  [Void]$StringBuilder.AppendLine("        Method      = 'POST'")
  [Void]$StringBuilder.AppendLine("        Body        = `$Body")
  [Void]$StringBuilder.AppendLine("        Uri         = `$TokenUri")
  [Void]$StringBuilder.AppendLine("        UseBasicParsing = `$True")
  [Void]$StringBuilder.AppendLine("        ErrorAction = 'SilentlyContinue'")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Use the self-generated JWT as Authorization")
  [Void]$StringBuilder.AppendLine("      `$AuthResult = Invoke-RestMethod @PostSplat")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      # Check if we received an access token in the response")
  [Void]$StringBuilder.AppendLine("      if ([String]::IsNullOrEmpty(`$AuthResult.Access_Token))")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Failed to Authenticate")
  [Void]$StringBuilder.AppendLine("        @{")
  [Void]$StringBuilder.AppendLine("          `"ExpiresIn`" = [DateTime]::MinValue")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      else")
  [Void]$StringBuilder.AppendLine("      {")
  [Void]$StringBuilder.AppendLine("        # Successful Authentication")
  [Void]$StringBuilder.AppendLine("        @{")
  [Void]$StringBuilder.AppendLine("          `"Content-Type`"  = `"application/json`"")
  [Void]$StringBuilder.AppendLine("          `"Authorization`" = `"Bearer `" + `$AuthResult.Access_Token")
  [Void]$StringBuilder.AppendLine("          `"ExpiresIn`"     = [DateTime]::Now.AddSeconds(`$AuthResult.Expires_In - 300)")
  [Void]$StringBuilder.AppendLine("        }")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      # Cert Not Found - Failed to Authenticate")
  [Void]$StringBuilder.AppendLine("      @{")
  [Void]$StringBuilder.AppendLine("        `"ExpiresIn`" = [DateTime]::MinValue")
  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  catch")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    # Error Accessing Certificate - Failed to Authenticate")
  [Void]$StringBuilder.AppendLine("    @{")
  [Void]$StringBuilder.AppendLine("      `"ExpiresIn`" = [DateTime]::MinValue")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  Write-Verbose -Message `"Exit Function Get-MyOAuthCertToken`"")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("#endregion function Get-MyOAuthCertToken")
  [Void]$StringBuilder.AppendLine("")
