  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  [Void]`$Message.Add(`"saveToSentItems`", (`$SaveToSent.IsPresent.ToString()))")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  if (`$PSCmdlet.ParameterSetName -eq `"Me`")")
  [Void]$StringBuilder.AppendLine("  {")
