  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  `$Result = Invoke-WebRequest -UseBasicParsing -Uri `$Uri -Headers `$AuthToken -Method Post -Body (`$Message | ConvertTo-Json -Depth 99)")
