  [Void]$StringBuilder.AppendLine("    `$Uri = `"https://`$(`$TenantName).sharepoint.com/sites/`$(`$SiteName)/_api/web/lists`$(`$TmpGetBy)/Items(`$(`$ItemID))/AttachmentFiles/getByFileName('{0}')`"")
  [Void]$StringBuilder.AppendLine("  }")
