  [Void]$StringBuilder.AppendLine("  ")
  [Void]$StringBuilder.AppendLine("  `$Uri = `"https://`$(`$TenantName).sharepoint.com/sites/`$(`$SiteName)/_api/web/lists`$(`$TmpGetBy)/Items(`$(`$ItemID))/AttachmentFiles/add(FileName='{0}')`"")
