  [Void]$StringBuilder.AppendLine("        Get-MyTableQuery -StorageAccount `$StorageAccount -AccessKey `$AccessKey -TableName `$TableName -Query `"PartitionKey eq '`$(`"PKey{0}`" -f `$C)' and  RowKey eq '`$(`"RKey{0}`" -f `$C)'`" -Select Text, Double")
