  [Void]$StringBuilder.AppendLine("  [Void]`$StringBuilder.Clear()")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  Write-Verbose -Message `"Exit Function `$(`$MyInvocation.MyCommand)`"")
  [Void]$StringBuilder.AppendLine("}")
