  [Void]$StringBuilder.AppendLine("      New-HTMLSelect -Id `"State`" -Name `"State`" -Options `$Options -Multiple -Size 3 -Autocomplete `"on`" -TabIndex 1 -Title `"Select a State`"")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
