  [Void]$StringBuilder.AppendLine("    .PARAMETER OnDblClick")
  [Void]$StringBuilder.AppendLine("      [string] Adds the 'ondblclick' event handler to the select element.")
  [Void]$StringBuilder.AppendLine("      Example:")
  [Void]$StringBuilder.AppendLine("        var clickedElement = document.elementFromPoint(event.clientX, event.clientY);")
  [Void]$StringBuilder.AppendLine("        if (clickedElement && clickedElement.tagName === ``OPTGROUP``) {")
  [Void]$StringBuilder.AppendLine("          var elements = document.querySelectorAll(``[id=`${clickedElement.label}]``);")
  [Void]$StringBuilder.AppendLine("          elements.forEach(el => {")
  [Void]$StringBuilder.AppendLine("            if (el.style.display === ``none``) {")
  [Void]$StringBuilder.AppendLine("              el.style.display = ``block``;")
  [Void]$StringBuilder.AppendLine("            } else {")
  [Void]$StringBuilder.AppendLine("              el.style.display = ``none``;")
  [Void]$StringBuilder.AppendLine("              if (el.selected)")
  [Void]$StringBuilder.AppendLine("              {")
  [Void]$StringBuilder.AppendLine("                el.selected = false;")
