  [Void]$StringBuilder.AppendLine("      New-HTMLSelectExpand -Id `"State`" -Name `"State`" -Options `$Options -Multiple -Size 3 -Autocomplete `"on`" -TabIndex 1 -Title `"Select a State or Province`"")
  [Void]$StringBuilder.AppendLine("    .EXAMPLE")
