  [Void]$StringBuilder.AppendLine("      New-HTMLSelectExpand -Id `"State`" -Name `"State`" -Options `$Options -OnChange `"alert('Changed!')`" -OnClick `"console.log('Clicked!')`" -OnFocus `"this.style.backgroundColor='yellow'`" -OnBlur `"this.style.backgroundColor=''`" -OnKeyDown `"console.log('Key Down!')`" -OnKeyUp `"console.log('Key Up!')`" -OnKeyPress `"console.log('Key Press!')`" -OnMouseDown `"console.log('Mouse Down!')`" -OnMouseUp `"console.log('Mouse Up!')`" -OnMouseEnter `"console.log('Mouse Enter!')`" -OnMouseLeave `"console.log('Mouse Leave!')`" -OnMouseMove `"console.log('Mouse Move!')`" -OnMouseOver `"console.log('Mouse Over!')`" -OnMouseOut `"console.log('Mouse Out!')`" -OnContextMenu `"return false;`"")
