  [Void]$StringBuilder.AppendLine("  if (`$Required.IsPresent)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [void]`$StringBuilder.Append(`" required`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  if (`$PSBoundParameters.ContainsKey(`"Size`"))")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [void]`$StringBuilder.Append(`" size='`$(`$Size)'`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  if (`$PSBoundParameters.ContainsKey(`"Style`"))")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [void]`$StringBuilder.Append(`" style='`$(`$Style)'`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  if (`$PSBoundParameters.ContainsKey(`"TabIndex`"))")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [void]`$StringBuilder.Append(`" tabindex='`$(`$TabIndex)'`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  if (`$PSBoundParameters.ContainsKey(`"Title`"))")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    [void]`$StringBuilder.Append(`" title='`$(`$Title)'`")")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("  ")
  [Void]$StringBuilder.AppendLine("  # Add event handler attributes if using EventHandelers parameter set")
  [Void]$StringBuilder.AppendLine("  if (`$PSCmdlet.ParameterSetName -eq `"EventHandelers`")")
  [Void]$StringBuilder.AppendLine("  {")
