  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" onchange='`$(`$OnChange)'`")")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    if (`$PSBoundParameters.ContainsKey(`"OnClick`"))")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" onclick='`$(`$OnClick)'`")")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    if (`$PSBoundParameters.ContainsKey(`"OnDblClick`"))")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" ondblclick='`$(`$OnDblClick)'`")")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    if (`$PSBoundParameters.ContainsKey(`"OnFocus`"))")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" onfocus='`$(`$OnFocus)'`")")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    if (`$PSBoundParameters.ContainsKey(`"OnBlur`"))")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" onblur='`$(`$OnBlur)'`")")
