  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      [void]`$StringBuilder.Append(`" onmouseout='`$(`$OnMouseOut)'`")")
  [Void]$StringBuilder.AppendLine("    }")
