  #region Class CyberArkAccount
  [Void]$StringBuilder.AppendLine("#region Class CyberArkAccount")
  [Void]$StringBuilder.AppendLine("Class CyberArkAccount")
  [Void]$StringBuilder.AppendLine("{")
