  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Create New Object ConStructor")
  [Void]$StringBuilder.AppendLine("  CyberArkAccount ([String]`$ID, [String]`$Name, [String]`$Domain, [String]`$UserName)")
