  [Void]$StringBuilder.AppendLine("    `$This.Name = `$Name")
  [Void]$StringBuilder.AppendLine("    `$This.Domain = `$Domain")
  [Void]$StringBuilder.AppendLine("    `$This.UserName = `$UserName")
