  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a hyperlink to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddLink ([String]`$Message, [String]`$LinkText, [String]`$URL)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<p>`$(`$Message) <a href='`$(`$URL)'>`$(`$LinkText)</a></p>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add HTML to the e-mail message body")
