  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to Set Default List Style")
  [Void]$StringBuilder.AppendLine("  [Void] SetListStyle ()")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SetListStyle(`$This.ListColor)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to Set Custom List Style")
  [Void]$StringBuilder.AppendLine("  [Void] SetListStyle ([String]`$ItemColor)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<style>ul, ol {color: `$(`$ItemColor);} ul li, ol li {color: `$(`$ItemColor);} ul li::marker, ol li::marker {color: `$(`$ItemColor);}</style>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a ul list to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddList ([String[]]`$ListItems)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddList(`$ListItems, `$False)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a ul/ol list to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddList ([String[]]`$ListItems, [Bool]`$Ordered)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = (`$ListItems | ForEach-Object -Process { `"<li>`$(`$PSItem)</li>`" }) -join ''")
  [Void]$StringBuilder.AppendLine("    if (`$Ordered)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append(`"<div class='data-table-wrapper'><ol>`$(`$TmpString)</ol></div>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append(`"<div class='data-table-wrapper'><ul>`$(`$TmpString)</ul></div>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a ul list to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddList ([HashTable]`$ListItems)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddList(`$ListItems, `$False)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a ul/ol list to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddList ([HashTable]`$ListItems, [Bool]`$Ordered)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = (`$ListItems.GetEnumerator() | ForEach-Object -Process { `"<li><b>`$(`$PSItem.Key): </b>`$(`$PSItem.Value)</li>`" }) -join ''")
  [Void]$StringBuilder.AppendLine("    if (`$Ordered)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append(`"<div class='data-table-wrapper'><ol>`$(`$TmpString)</ol></div>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append(`"<div class='data-table-wrapper'><ul>`$(`$TmpString)</ul></div>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to Set Default Table Style")
  [Void]$StringBuilder.AppendLine("  [Void] SetTableStyle ()")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SetTableStyle(`$This.TitleColor, `$This.ColumnColor, `$This.TextColor, `$This.BorderColor)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to Set Custom Table Style")
  [Void]$StringBuilder.AppendLine("  [Void] SetTableStyle ([String]`$TitleColor, [String]`$ColumnColor, [String]`$TextColor, [String]`$BorderColor)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<style>.data-table-wrapper {margin: 16px 0; overflow-x: auto;} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table {border-collapse: collapse; font-size: 14px; color: `$(`$TextColor);} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .table-title, .data-table .col-header {font-size: 16px; text-align: center; font-weight: bold;} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .table-title {color: `$(`$TitleColor);} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .col-header {color: `$(`$ColumnColor);} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .table-title, .data-table .col-header, .data-table .col-right, .data-table .col-left, .data-table .cell-left, .data-table .cell-center, .data-table .cell-right {padding: 2px 8px; white-space: nowrap; border: 1px solid `$(`$BorderColor);} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .col-right {text-align: right; font-weight: bold;} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .col-left, .data-table .cell-left {text-align: left;} ``")
  [Void]$StringBuilder.AppendLine("                            .data-table .cell-center {text-align: center;} ``")
  [Void]$StringBuilder.AppendLine("                    </style>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table title row to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableTitle ([Int]`$ColumnCount, [String]`$TitleText, [Bool]`$EndTitle)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddTableTitle(`$This.TitleInfo, `$ColumnCount, `$TitleText, `$EndTitle)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table title row to the e-mail message body with a custom background color")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableTitle ([String]`$BackgroundColor, [Int]`$ColumnCount, [String]`$TitleText, [Bool]`$EndTitle)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = `"<div class='data-table-wrapper'><table class='data-table'><thead><tr style='background-color:{0}; '><th class='table-title' colspan='{1}'>{2}</th></tr>{3}`"")
  [Void]$StringBuilder.AppendLine("    if (`$EndTitle)")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append([String]::Format(`$TmpString, `$BackgroundColor, `$ColumnCount, `$TitleText, `"</thead><tbody>`")) | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    else")
  [Void]$StringBuilder.AppendLine("    {")
  [Void]$StringBuilder.AppendLine("      `$This.SB.Append([String]::Format(`$TmpString, `$BackgroundColor, `$ColumnCount, `$TitleText, `"`")) | Out-Null")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table column header row to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableColumns ([String[]]`$ColumnNames)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddTableColumns(`$This.ColumnInfo, `$ColumnNames)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table column header row to the e-mail message body with a custom background color")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableColumns ([String]`$BackgroundColor, [String[]]`$ColumnNames)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = `"<tr style='background-color:`$(`$BackgroundColor); '>`$((@(1..`$(`$ColumnNames.Count)) | ForEach-Object -Process { `"<th class='col-header'>{`$(`$PSItem - 1)}</th>`" }) -join '')</tr></thead><tbody>`"")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append([String]::Format(`$TmpString, [Object[]]`$ColumnNames)) | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table row with a status column to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableRow ([String]`$StatusColor, [String]`$StatusText, [String[]]`$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddTableRow(`$This.BodyColor, `$StatusColor, `$StatusText, `$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table row with a status column to the e-mail message body with a custom background color")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableRow ([String]`$BackgroundColor, [String]`$StatusColor, [String]`$StatusText, [String[]]`$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = `"<tr style='background-color:`$(`$BackgroundColor)'><td class='cell-center' style='color:`$(`$StatusColor);  font-weight:bold; '>`$(`$StatusText)</td>`$((@(1..`$(`$ColumnValues.Count)) | ForEach-Object -Process { `"<td class='cell-left'>{`$(`$PSItem - 1)}</td>`" }) -join '')</tr>`"")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append([String]::Format(`$TmpString, [Object[]]`$ColumnValues)) | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table row to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableRow ([String[]]`$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddTableRow(`$This.BodyColor, `$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a table row to the e-mail message body with a custom background color")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableRow ([String]`$BackgroundColor, [String[]]`$ColumnValues)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$TmpString = `"<tr style='background-color:`$(`$BackgroundColor)'>`$((@(1..`$(`$ColumnValues.Count)) | ForEach-Object -Process { `"<td class='cell-left'>{`$(`$PSItem - 1)}</td>`" }) -join '')</tr>`"")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append([String]::Format(`$TmpString, [Object[]]`$ColumnValues)) | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a property/value pair row to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableProperty ([String]`$PropertyName, [String]`$PropertyValue)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.AddTableProperty(`$This.PropertyColor, `$PropertyName, `$This.ValueColor, `$PropertyValue)")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a property/value pair row to the e-mail message body with custom background colors")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableProperty ([String]`$PropertyBackgroundColor, [String]`$PropertyName, [String]`$ValueBackgroundColor, [String]`$PropertyValue)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<tr><td class='col-right' style='background-color:`$(`$PropertyBackgroundColor); '>`$(`$PropertyName):</td><td class='col-left' style='background-color:`$(`$ValueBackgroundColor); '>`$(`$PropertyValue)</td></tr>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to end the table and add spacing after the table in the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddTableEnd ()")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"</tbody></table>&nbsp;</div>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a signature block to the e-mail message body")
  [Void]$StringBuilder.AppendLine("  [Void] AddSignature ([String]`$Signature, [String]`$Message)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<div class='email-signature'><div class='sig-name' style='font-weight: bold;'>`$(`$Signature)</div><div class='sig-message'>`$(`$Message)</div></div><br><br></body>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to add a signature block to the e-mail message body with an optional URL")
  [Void]$StringBuilder.AppendLine("  [Void] AddSignature ([String]`$Signature, [String]`$Message, [String]`$URLText, [String]`$URLLink)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    `$This.SB.Append(`"<div class='email-signature'><hr><div class='sig-name' style='font-weight: bold;'>`$(`$Signature)</div><div class='sig-message'>`$(`$Message)</div><div><a href='`$(`$URLLink)' target='_blank'>`$(`$URLText)</a></div></div><br><br></body>`") | Out-Null")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  # Method to retrieve the generated e-mail message body as a string")
  [Void]$StringBuilder.AppendLine("  [String] GetEMailBody ()")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    return `$This.SB.ToString()")
  [Void]$StringBuilder.AppendLine("  }")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("#endregion class EMailMsg - Generate HTML E-mail Messages with Custom Colors and Styles")
  [Void]$StringBuilder.AppendLine("")  
  #endregion ******** Generate E-Mail Class ********

  #region ******** Generate E-Mail Sample Code ********
  [Void]$StringBuilder.AppendLine("#region Generate / Send Sample E-Mail")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("<#")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Create an instance of the EMailMsg class and generate the e-mail content")
  [Void]$StringBuilder.AppendLine("`$EMailMsg = [EMailMsg]::new(`"This is My Example E-Mail Header Message`", `$Base64Logo, 200, 38)")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Add Message Text")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddText(`"Dear Sir or Madam,`")")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddText(`"This is a test e-mail generated by PowerShell.<br>Below you can find some example tables with different styles and content.`")")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddMailTo(`"To Respond to this e-mail`", `"Click here`", (`$MailParams.From), (`$MailParams.To), `"Sample E-Mail Subject`", `"Greetings,%0A%0AThis is a sample e-mail body generated by PowerShell.%0A`")")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddLink(`"For more information`", `"Click here`", `"https://some.website.net/`")")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Add List")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.SetListStyle()")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddList(@(`"Item 1`", `"Item 2`", `"Item 3`", `"Item 4`"), `$False)")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Add Property/Value Tables")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.SetTableStyle()")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableTitle(2, `"Property Table Title`", `$True)")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableProperty(`"Property 1`", `"Value 1`")")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableProperty(`"Property 2`", `"Value 2`")")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableEnd()")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Add Info/Data Table")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableTitle(5, `"Info Test Table Title`", `$False)")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableColumns(@(`"Status`", `"Column 1`", `"Column 2`", `"Column 3`", `"Column 4`"))")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableRow((`$EMailMsg.RowColor[0]), `$EMailMsg.StatusInfo, `"Information`", @(`"Value 1`", `"Value 2`", `"Value 3`", `"Value 4`"))")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableRow((`$EMailMsg.RowColor[1]), `$EMailMsg.StatusSuccess, `"Success`", @(`"Value 1`", `"Value 2`", `"Value 3`", `"Value 4`"))")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableRow((`$EMailMsg.RowColor[0]), `$EMailMsg.StatusWarning, `"Warning`", @(`"Value 1`", `"Value 2`", `"Value 3`", `"Value 4`"))")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableRow((`$EMailMsg.RowColor[1]), `$EMailMsg.StatusError, `"Error`", @(`"Value 1`", `"Value 2`", `"Value 3`", `"Value 4`"))")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddTableEnd()")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Add Signature")
  [Void]$StringBuilder.AppendLine("`$EMailMsg.AddSignature(`"Best regards,`", `"This was a example e-mail generated by PowerShell.`", `"Some Web Site`", `"https://some.website.net/`")")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Send E-Mail Parameters")
  [Void]$StringBuilder.AppendLine("`$MailParams = @{")
  [Void]$StringBuilder.AppendLine("  `"SmtpServer`"    = `"smtphost.fakedomain.qaz`"")
  [Void]$StringBuilder.AppendLine("  `"Port`"          = 25")
  [Void]$StringBuilder.AppendLine("  `"From`"          = `"gomer.pyle@fakedomain.qaz`"")
  [Void]$StringBuilder.AppendLine("  `"to`"            = `"gomer.pyle@fakedomain.qaz`"")
  [Void]$StringBuilder.AppendLine("  `"BodyAsHtml`"    = `$True")
  [Void]$StringBuilder.AppendLine("  `"WarningAction`" = `"SilentlyContinue`"")
  [Void]$StringBuilder.AppendLine("}")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("# Send the e-mail using Send-MailMessage")
  [Void]$StringBuilder.AppendLine("Send-MailMessage @MailParams -Body (`$EMailMsg.GetEMailBody()) -Subject `"PowerShell Generated Example E-Mail`"")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("#>")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("#endregion Generate / Send Sample E-Mail")
  [Void]$StringBuilder.AppendLine("")
  #endregion ******** Generate E-Mail Sample Code ********

  [Void]$StringBuilder.AppendLine("#endregion ******** Generate E-Mail Class ********")
  [Void]$StringBuilder.AppendLine("")
  #endregion ******** My Code ********

  $StringBuilder.ToString()
  $StringBuilder = $Null

  [System.GC]::Collect()
  [System.GC]::WaitForPendingFinalizers()

  Write-Verbose -Message "Exit Function Build-MyFCGScriptGenEMail"
}
#endregion function Build-MyFCGScriptGenEMail

#region function Build-MyFCGScriptMultiThread
Function Build-MyFCGScriptMultiThread ()
{
  <#
    .SYNOPSIS
      Function to do something specific
    .DESCRIPTION
      Function to do something specific
    .PARAMETER Value
      Value Command Line Parameter
    .EXAMPLE
      Build-MyFCGScriptMultiThread -Value "String"
    .NOTES
      Original Function By
  #>
  [CmdletBinding()]
  Param (
    [parameter(Mandatory = $True)]
    [String]$ScriptName
  )
  Write-Verbose -Message "Enter Function Build-MyFCGScriptMultiThread"

  $StringBuilder = [System.Text.StringBuilder]::New()

  #region ******** My Code ********
  [Void]$StringBuilder.AppendLine("#region ******** Multiple Thread Functions ********")
  [Void]$StringBuilder.AppendLine("")

  #region ******** Custom Objects MyRSPool / MyRSJob  ********
  [Void]$StringBuilder.AppendLine("#region ******** Custom Objects MyRSPool / MyRSJob ********")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("`$MyCode = @`"")
  [Void]$StringBuilder.AppendLine("using System;")
  [Void]$StringBuilder.AppendLine("using System.Collections.Generic;")
  [Void]$StringBuilder.AppendLine("using System.Management.Automation;")
  [Void]$StringBuilder.AppendLine("using System.Threading;")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("public class MyRSJob")
  [Void]$StringBuilder.AppendLine("{")
  [Void]$StringBuilder.AppendLine("  private System.String _Name;")
  [Void]$StringBuilder.AppendLine("  private System.String _PoolName;")
  [Void]$StringBuilder.AppendLine("  private System.Guid _PoolID;")
  [Void]$StringBuilder.AppendLine("  private System.Management.Automation.PowerShell _PowerShell;")
  [Void]$StringBuilder.AppendLine("  private System.IAsyncResult _PowerShellAsyncResult;")
  [Void]$StringBuilder.AppendLine("  private System.Object _InputObject = null;")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("  public MyRSJob(System.String Name, System.Management.Automation.PowerShell PowerShell, System.IAsyncResult PowerShellAsyncResult, System.Object InputObject, System.String PoolName, System.Guid PoolID)")
  [Void]$StringBuilder.AppendLine("  {")
  [Void]$StringBuilder.AppendLine("    _Name = Name;")
  [Void]$StringBuilder.AppendLine("    _PoolName = PoolName;")
