  [Void]$StringBuilder.AppendLine("      }")
  [Void]$StringBuilder.AppendLine("      `$StopWatch.Stop()")
  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    ")
  [Void]$StringBuilder.AppendLine("    if (`$PassThru.IsPresent)")
  [Void]$StringBuilder.AppendLine("    {")
