  [Void]$StringBuilder.AppendLine("    }")
  [Void]$StringBuilder.AppendLine("    `$WaitJobs.Clear()")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("    Write-Verbose -Message `"Exit Function Wait-MyRSJob End Block`"")
  [Void]$StringBuilder.AppendLine("  }")
