  [Void]$StringBuilder.AppendLine("      Remove-MyRSJob -PoolID `$PoolID")
  [Void]$StringBuilder.AppendLine("")
  [Void]$StringBuilder.AppendLine("      Remove all RSJobs in the Specified RSPool")
